/**
 * The notice that belongs to the application frame and stays until its cause ends (`design/components/banner.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/banner.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Icon,
  agentMember,
  claimSlot,
  elementRef,
  focusAfterRemoval,
  resolveSlot,
  scope,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/banner.module.css'
import Button from '../controls/Button'

export type BannerTone = NonNullable<BannerProps['tone']>

export interface BannerProps {
  /**
   * One `ghost` or `soft` `sm` Button, or one Link: the way out of the condition.
   */
  action?: JSX.Element
  /**
   * The message, in a sentence or two.
   */
  children: JSX.Element
  /**
   * The ✕'s accessible name, default `Dismiss`; localized hosts pass their own.
   */
  dismissLabel?: string
  /**
   * Renders the ✕. The app removes the Banner; it passes this only where hiding it is safe.
   */
  onDismiss?: () => void
  tone?: 'info' | 'warning' | 'danger' | 'neutral'
}

/** The notice that belongs to the application frame and stays until its cause ends. */
export default function Banner(given: BannerProps): JSX.Element {
  const props = mergeProps(
    { tone: 'neutral', dismissLabel: 'Dismiss' } as Defaults<BannerProps, 'tone' | 'dismissLabel'>,
    claimSlot(given),
  )
  return scope(() => {
    const closeRegion = elementRef<HTMLElement>()
    const root = elementRef<HTMLElement>()
    const actionSlot = resolveSlot(() => props.action)
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = focusAfterRemoval(root.value)
      release1 = () => {
        ran()
      }
    }
    watchEffect(
      createMemo(() => root.value),
      effect1,
      true,
    )
    onCleanup(() => release1?.())
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = agentMember({
        member: 'Banner',
        element: () => root.value,
        state: () => ({ tone: props.tone, dismissible: props.onDismiss !== undefined }),
        actions: {
          dismiss: () =>
            (() => {
              if (!(props.onDismiss !== undefined))
                throw new Error('This banner has no dismiss control.')
              props.onDismiss?.()
            })(),
        },
        withholds: () => closeRegion.value,
      })
      release2 = () => {
        ran()
      }
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    return (
      <div
        class={styles.banner}
        role={props.tone === 'danger' ? 'alert' : 'status'}
        data-tone={props.tone}
        data-member="banner"
        ref={root.attach}
      >
        {props.tone !== 'neutral' ? (
          <span class={styles.glyph}>
            <Icon
              name={
                props.tone === 'danger' ? 'error' : props.tone === 'warning' ? 'warning' : 'info'
              }
            />
          </span>
        ) : null}
        {/* content */}
        <div class={styles.content}>
          {/* text */}
          <div class={styles.text}>{props.children}</div>
          {actionSlot.filled() ? <div class={styles.action}>{actionSlot()}</div> : null}
        </div>
        {props.onDismiss !== undefined ? (
          <div class={styles.close} ref={closeRegion.attach}>
            <Button
              variant="ghost"
              tone="neutral"
              size="sm"
              iconOnly={true}
              icon="close"
              label={props.dismissLabel}
              onClick={() => props.onDismiss?.()}
            />
          </div>
        ) : null}
      </div>
    )
  })
}
